    '<div><dt>Issued</dt><dd>' + escapeHtml(displayDate(invoice.issue_date)) + '</dd></div>',
    '<div><dt>Due</dt><dd>' + escapeHtml(displayDate(invoice.due_date)) + '</dd></div>',
    '<div><dt>PO number</dt><dd>' + escapeHtml(invoice.po_number || 'None') + '</dd></div></dl>',
